ST.xhtml:
// alarms: check the measurement first
alarm(pv := plant.y, ack := ackBtn, reset := resetBtn);

// controller: reads the measurement from the previous scan
// interlock forces manual mode with the valve closed (0 %)
ctrl(sp := sp, pv := plant.y, useSmith := useSmith,
     manualMode := manualMode OR alarm.interlock,
     manualOut  := SEL(alarm.interlock, manualOut, 0.0),
     filterOn := filterOn);
valve := ctrl.u;

// simulated heat exchanger
plant(u := valve, dist := dist, gainFactor := gainFactor,
      delayFactor := delayFactor, noiseOn := noiseOn);
temp := plant.y;

alpha := EXP(-Ts / tau);
beta  := EXP(-Ts / tauS);

// delay in samples, limited to the buffer size
nd := REAL_TO_INT(theta * delayFactor / Ts);
IF nd < 0 THEN nd := 0; END_IF
IF nd > 399 THEN nd := 399; END_IF

// delay buffer: store the new input, read the old one
buf[wr] := u + dist;
rd := wr - nd;
IF rd < 0 THEN rd := rd + 400; END_IF
ud := buf[rd];
wr := wr + 1;
IF wr > 399 THEN wr := 0; END_IF

// plant lag and sensor lag
x  := alpha * x  + (1.0 - alpha) * K * gainFactor * ud;
ys := beta  * ys + (1.0 - beta)  * x;
yClean := ys;

// measurement noise, about 0.05 degC standard deviation
sumU := 0.0;
FOR i := 1 TO 12 DO
    seed := seed * DWORD#1664525 + DWORD#1013904223;
    sumU := sumU + DWORD_TO_REAL(seed) / 4294967296.0;
END_FOR
IF noiseOn THEN
    y := ys + 0.05 * (sumU - 6.0);
ELSE
    y := ys;
END_IF

pTerm := Kc * err;

IF manual THEN
    // follow the operator value, so switching back to auto causes no jump
    intg := manualOut - pTerm;
    u := LIMIT(outMin, manualOut, outMax);
ELSE
    IF Ti > 0.001 THEN
        intgNew := intg + Kc * err * Ts / Ti;
    ELSE
        intgNew := intg;
    END_IF
    uCand := pTerm + intgNew;

    // anti-windup: stop integrating while the output is saturated
    // and the error would push it further into the limit
    IF (uCand > outMax AND err > 0.0) OR (uCand < outMin AND err < 0.0) THEN
        ;
    ELSE
        intg := intgNew;
    END_IF
    u := LIMIT(outMin, pTerm + intg, outMax);
END_IF

alpha := EXP(-Ts / tau);
beta  := EXP(-Ts / tauS);

// model delay in samples
nd := REAL_TO_INT(theta / Ts);
IF nd < 0 THEN nd := 0; END_IF
IF nd > 399 THEN nd := 399; END_IF

// delay buffer for the model with delay
buf[wr] := u;
rd := wr - nd;
IF rd < 0 THEN rd := rd + 400; END_IF
ud := buf[rd];
wr := wr + 1;
IF wr > 399 THEN wr := 0; END_IF

// model without delay: plant lag, then sensor lag
x0  := alpha * x0  + (1.0 - alpha) * K * u;
ys0 := beta  * ys0 + (1.0 - beta)  * x0;

// model with delay: same, but fed with the delayed input
x1  := alpha * x1  + (1.0 - alpha) * K * ud;
ys1 := beta  * ys1 + (1.0 - beta)  * x1;

ym0  := ys0;
ym   := ys1;
corr := ym0 - ym;

// measurement filter (first order), can be switched off
IF filterOn AND (Tf > 0.0) THEN
    pvF := pvF + Ts / (Tf + Ts) * (pv - pvF);
ELSE
    pvF := pv;
END_IF

// errors for the two controllers
errPI := sp - pvF;
errSM := sp - pvF - smith.corr;   // correction from the previous scan

// value the idle controller follows (keeps switching bumpless)
IF manualMode THEN
    mo := manualOut;
ELSE
    mo := uPrev;
END_IF

piPlain(err := errPI, Kc := KcPI, Ti := TiPI,
        manual := (manualMode OR useSmith), manualOut := mo);
piSmith(err := errSM, Kc := KcSM, Ti := TiSM,
        manual := (manualMode OR NOT useSmith), manualOut := mo);

// select the output
IF manualMode THEN
    u := LIMIT(0.0, manualOut, 100.0);
ELSIF useSmith THEN
    u := piSmith.u;
ELSE
    u := piPlain.u;
END_IF
uPrev := u;

// run the predictor models with the new valve command
smith(u := u);
corr := smith.corr;

IF high THEN condH := pv > (tahLimit - deadband);
ELSE condH := pv > tahLimit; END_IF
tonH(IN := condH, PT := T#2S);
high := tonH.Q;

IF highHigh THEN condHH := pv > (tahhLimit - deadband);
ELSE condHH := pv > tahhLimit; END_IF
tonHH(IN := condHH, PT := T#2S);
highHigh := tonHH.Q;

sensorFault := (pv < -5.0) OR (pv > 60.0);

anyActive := high OR highHigh OR sensorFault;
   rtH(CLK := high);
   rtHH(CLK := highHigh);
   rtSF(CLK := sensorFault);
rtAck(CLK := ack);
rtReset(CLK := reset);

IF rtH.Q OR rtHH.Q OR rtSF.Q THEN unacked := TRUE; END_IF
IF rtAck.Q THEN unacked := FALSE; END_IF
horn := unacked;

IF anyActive THEN
    IF unacked THEN state := 1; ELSE state := 2; END_IF
ELSE
    IF unacked THEN state := 3; ELSE state := 0; END_IF
END_IF

IF highHigh OR sensorFault THEN interlock := TRUE; END_IF
IF rtReset.Q AND NOT highHigh AND NOT sensorFault AND (pv < tahLimit) THEN
    interlock := FALSE;
END_IF
